// Encode bounded binary identifiers for JSON without exposing keys.
static String toHex(const uint8_t* input, size_t size) {
  static const char digits[] = "0123456789abcdef";
  String result;
  if (!result.reserve(size * 2)) return result;
  for (size_t i = 0; i < size; i++) { result += digits[input[i] >> 4]; result += digits[input[i] & 15]; }
  return result;
}

// Decode only complete, exact-length hexadecimal fields at the network boundary.
static bool fromHex(const char* input, uint8_t* output, size_t size) {
  if (!input || strnlen(input, size * 2 + 1) != size * 2) return false;
  for (size_t i = 0; i < size; i++) {
    unsigned value = 0;
    for (size_t j = 0; j < 2; j++) {
      char c = input[i * 2 + j];
      unsigned digit = c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : c >= 'A' && c <= 'F' ? c - 'A' + 10 : 16;
      if (digit > 15) return false;
      value = value * 16 + digit;
    }
    output[i] = value;
  }
  return true;
}

// Use Mbed TLS authenticated encryption; no plaintext is applied before tag verification.
static bool crypt(bool encrypt, const uint8_t* key, const uint8_t* nonce, const uint8_t* aad, size_t aadLength,
                  const uint8_t* input, size_t length, uint8_t* output, uint8_t* tag) {
  mbedtls_gcm_context context;
  mbedtls_gcm_init(&context);
  int result = mbedtls_gcm_setkey(&context, MBEDTLS_CIPHER_ID_AES, key, 256);
  if (!result) {
    if (encrypt) result = mbedtls_gcm_crypt_and_tag(&context, MBEDTLS_GCM_ENCRYPT, length, nonce, 12, aad, aadLength, input, output, TAG_SIZE, tag);
    else result = mbedtls_gcm_auth_decrypt(&context, length, nonce, 12, aad, aadLength, tag, TAG_SIZE, input, output);
  }
  mbedtls_gcm_free(&context);
  return result == 0;
}

// Domain-separated sender/boot keys make each monotonically numbered nonce unique per key.
static bool deriveKey(const uint8_t* id, const uint8_t* boot, uint8_t* key) {
  static constexpr char DOMAIN[] = "inter_comms/node/v1";
  constexpr size_t DOMAIN_SIZE = sizeof(DOMAIN) - 1;
  uint8_t material[DOMAIN_SIZE + 6 + 16] = {};
  memcpy(material, DOMAIN, DOMAIN_SIZE);
  memcpy(material + DOMAIN_SIZE, id, 6);
  memcpy(material + DOMAIN_SIZE + 6, boot, 16);
  return mbedtls_md_hmac(mbedtls_md_info_from_type(MBEDTLS_MD_SHA256), INTER_COMMS_GROUP_KEY, 32, material, sizeof(material), key) == 0;
}
